def emit_file(path, leftover_n, start, svc_ok, svc_bad, dash_letter, leftover_words, ticket0, ban, last_ban, rows, fn):
    words = " leftover" * leftover_n
    header = f'''"""Observability leftover{leftover_n} plants r{start}+.

BAN {last_ban}, leftover{leftover_n-1} prior mill, leftover12 lock-basin,
r875 tempo-ingester-max-traces-per-user-one, r384 otel-forward-connector,
PagerDuty orch, Opsgenie alias, Rootly urgency.
"""

from mill_plants_t import _leftover_pair

MORE = []
ROUND_PAIRS = {{}}


def _emit(round_n, **kwargs):
    dest = []
    _leftover_pair(n=str(round_n), dest=dest, **kwargs)
    MORE.extend(dest)
    ROUND_PAIRS[round_n] = dest[0]


def {fn}(n, **kw):
    vendor, noun, prefix = kw["vendor"], kw["noun"], kw["prefix"]
    ok_svc, bad_svc = f"{svc_ok}-{{noun}}-svc", f"{svc_bad}-{{noun}}-svc"
    tag = noun.replace("-", "")[:8]
    vtag = prefix.replace("-", "")[:5]
    ok_dash, bad_dash = f"{{tag}}-{{vtag}}-{{n}}", f"{dash_letter}{{tag[:7]}}-{{vtag}}-fl"
    lie_core = kw["lie_core"]
    _emit(
        n,
        kind="grafana",
        ok_slug=kw["ok_slug"],
        bad_slug=kw["bad_slug"],
        ok_svc=ok_svc,
        bad_svc=bad_svc,
        ok_dash=ok_dash,
        bad_dash=bad_dash,
        panel=kw["panel"],
        metric="",
        needle=kw["needle"],
        lie=(
            f"{{vendor}}{words} {{lie_core}} "
            f"so Grafana dashboard {{ok_dash}} is empty while the source still 202"
        ),
        bad_lie=(
            f"{{kw['false_lead']}} does not restore{words} {{lie_core}}"
        ),
        false_lead=kw["false_lead"],
        avoided=kw["avoided"],
        this_is=f"{{vendor}}{words} {{lie_core}}",
        ticket=f"OBS-{{ {ticket0} + (n - {start}) }}",
        knob=kw["knob"],
        old=kw["old"],
        new=kw["new"],
        wrong_knob=kw["wrong_knob"],
        wrong_old=kw["wrong_old"],
        wrong_new=kw["wrong_new"],
        wrong2_old=kw["wrong2_old"],
        wrong2_new=kw["wrong2_new"],
        reload="grafana",
        config_path=f"{{prefix}}/{{tag}}-false.yaml",
        lie_path=f"{{prefix}}/{{tag}}-lie.yaml",
        bad_config=f"{{prefix}}/{dash_letter}{{tag[:7]}}-false.yaml",
        bad_lie_path=f"{{prefix}}/{dash_letter}{{tag[:7]}}-lie.yaml",
    )


BAN = (
    "{ban}"
)

SPECS = [
'''
    lines = [header]
    for spec in rows:
        (vendor, prefix, noun, panel, needle, ok_slug, bad_slug, lie_core, false_lead,
         knob, old, new, wrong_knob, wrong_old, wrong_new, wrong2_old, wrong2_new) = spec
        d = dict(
            vendor=vendor, ok_slug=ok_slug, bad_slug=bad_slug, noun=noun, panel=panel,
            needle=needle, lie_core=lie_core, false_lead=false_lead, avoided="BAN",
            knob=knob, old=old, new=new, wrong_knob=wrong_knob, wrong_old=wrong_old,
            wrong_new=wrong_new, wrong2_old=wrong2_old, wrong2_new=wrong2_new, prefix=prefix,
        )
        parts = []
        for k, v in d.items():
            if k == "avoided":
                parts.append("avoided=BAN")
            else:
                parts.append(f"{k}={v!r}")
        lines.append("    dict(" + ", ".join(parts) + "),\n")
    lines.append("]\n\n")
    lines.append(f"assert len(SPECS) == {len(rows)}, len(SPECS)\n")
    lines.append("for i, spec in enumerate(SPECS):\n")
    lines.append(f"    {fn}({start} + i, **spec)\n")
    path.write_text("".join(lines), encoding="utf-8")
    print(f"wrote {path} {len(rows)} specs start r{start}")


def main():
    assert len(L14) == 88, len(L14)
    assert len(L15) == 88, len(L15)
    for label, rows in (("L14", L14), ("L15", L15)):
        nouns = [r[2] for r in rows]
        prefixes = [r[1] for r in rows]
        slugs = [r[5] for r in rows] + [r[6] for r in rows]
        vendors = [r[0] for r in rows]
        assert len(set(nouns)) == len(nouns), [n for n in nouns if nouns.count(n) > 1]
        assert len(set(prefixes)) == len(prefixes), [p for p in prefixes if prefixes.count(p) > 1]
        assert len(set(slugs)) == len(slugs)
        assert len(set(vendors)) == len(vendors)
        vtags = [p.replace("-", "")[:5] for p in prefixes]
        assert len(set(vtags)) == len(vtags), [v for v in vtags if vtags.count(v) > 1]
        tags = [n.replace("-", "")[:8] for n in nouns]
        # fail dash unique within leftover: letter + tag[:7] + vtag
        fail = [t[:7] + "-" + v for t, v in zip(tags, vtags)]
        assert len(set(fail)) == len(fail), [x for x in fail if fail.count(x) > 1]
    emit_file(
        ROOT / "mill_plants_ag.py",
        leftover_n=14,
        start=1260,
        svc_ok="canal",
        svc_bad="reach",
        dash_letter="c",
        leftover_words=14,
        ticket0=9300,
        ban="r1259 wasmtime-log-drop-leftover; leftover13 dam/weir r1212-r1259; r875 tempo; r384 otel-forward; PagerDuty orch; Opsgenie alias; r515 Rootly urgency",
        last_ban="r1259 wasmtime-log-drop-leftover",
        rows=L14,
        fn="_l14",
    )
    emit_file(
        ROOT / "mill_plants_ah.py",
        leftover_n=15,
        start=1348,
        svc_ok="ford",
        svc_bad="creek",
        dash_letter="f",
        leftover_words=15,
        ticket0=9500,
        ban="r1347 apache-beam leftover14 canal/reach r1260-r1347; leftover13 dam/weir; r875 tempo; r384 otel-forward; PagerDuty orch; Opsgenie alias; r515 Rootly urgency",
        last_ban="r1347 beamx-metrics-off-leftover",
        rows=L15,
        fn="_l15",
    )


if __name__ == "__main__":
    main()
